// Logo officiel LSPD (PNG embarqué en base64 pour compatibilité Canvas sans CORS & ouverture locale file://)
export const LSPD_LOGO_DATA_URL = "data:image/png;base64,";

let _img = null;
let _readyPromise = null;

export function getLspdLogoImage() {
  if (typeof Image === "undefined") return null;
  if (!_img) {
    _img = new Image();
    _img.src = LSPD_LOGO_DATA_URL;
  }
  return _img;
}

export function ensureLspdLogoLoaded() {
  const img = getLspdLogoImage();
  if (!img) return Promise.resolve(null);
  if (img.complete && img.naturalWidth > 0) return Promise.resolve(img);
  if (!_readyPromise) {
    _readyPromise = new Promise(resolve => {
      img.onload = () => resolve(img);
      img.onerror = () => resolve(null);
    });
  }
  return _readyPromise;
}

// Précharge l'image immédiatement au démarrage
getLspdLogoImage();